def find_min_max(numbers):
  """Finds the largest and smallest number in a list."""
  if not numbers:
    return None, None
  largest = numbers[0]
  smallest = numbers[0]
  for number in numbers:
    if number > largest:
      largest = number
    if number < smallest:
      smallest = number
  return largest, smallest
